<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\ChatRole;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * One turn of a question thread: what the participant asked, or what the tutor
 * answered.
 *
 * The model name and token counts are kept only on the tutor's turns — they
 * describe a generation, and the participant's own message was not generated by
 * anything.
 */
#[Fillable(['question_chat_id', 'role', 'content', 'model', 'prompt_tokens', 'completion_tokens'])]
class QuestionChatMessage extends Model
{
    /**
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'role' => ChatRole::class,
            'prompt_tokens' => 'int',
            'completion_tokens' => 'int',
        ];
    }

    /**
     * @return BelongsTo<QuestionChat, $this>
     */
    public function chat(): BelongsTo
    {
        return $this->belongsTo(QuestionChat::class, 'question_chat_id');
    }

    public function isFromTutor(): bool
    {
        return $this->role->isFromTutor();
    }
}
